const j = $json;
const cvText = j.cvText || '';
const fieldOfWork = j.fieldOfWork || '';
const jobTitles = j.jobTitles || '';
const customerName = j.customerName || '';

const prompt = `أنت خبير تطوير مهني وتوظيف في السوق السعودي. عميلنا اسمه ${customerName || 'العميل'}، مجاله/تخصصه: ${fieldOfWork || 'غير محدد'}، والمسميات الوظيفية التي يستهدفها: ${jobTitles || 'غير محددة'}.

سيرته الذاتية الحالية:
${cvText || 'لا تتوفر سيرة ذاتية مفصّلة.'}

المطلوب منك تحليل الفجوة بين ما يملكه فعليًا وما يحتاجه ليتفوق في مجاله ويكون مطلوبًا أكثر في سوق العمل السعودي حاليًا. أرجع النتيجة بصيغة JSON فقط بدون أي نص إضافي قبله أو بعده وبدون Markdown، بالشكل التالي بالضبط:
{
  "certifications": [ {"name": "اسم الشهادة الاحترافية", "reason": "سبب موجز يوضح لماذا هذي الشهادة تحديدًا تفيده وترفع طلبه في السوق، ولماذا هي من أهم شهادتين ينقصانه"} ... بالضبط عنصرين اثنين فقط، أعلى شهادتين احترافيتين قيمة وطلبًا في السوق وغير موجودتين حاليًا في سيرته الذاتية ],
  "skills": [ {"name": "اسم المهارة", "reason": "سبب موجز يوضح كيف هذي المهارة تخدم تخصصه والوظائف اللي يستهدفها ولماذا مطلوبة بكثرة في السوق حاليًا"} ... بالضبط 5 عناصر، مهارات غير موجودة حاليًا في سيرته الذاتية ],
  "advice": "نصيحة عملية واحدة مركّزة (3-4 جمل) لتطوير سيرته الذاتية ومسيرته المهنية بشكل عام، مبنية على وضعه الحالي"
}
كل المحتوى بالعربية، ومبني فعليًا على تفاصيل سيرته الذاتية ومجاله وليس عامًا جدًا. لا تقترح شهادة أو مهارة مذكورة أصلًا في سيرته الذاتية.`;

return { json: { chatId: j.telegramChatId, customerName, prompt } };

function findText(obj) {
  if (typeof obj === 'string') return obj;
  if (!obj || typeof obj !== 'object') return '';
  if (typeof obj.content === 'string') return obj.content;
  if (Array.isArray(obj.content)) {
    const t = obj.content.find(function(c){ return c && c.type === 'text'; });
    if (t) return t.text || '';
  }
  if (typeof obj.text === 'string') return obj.text;
  if (obj.message && typeof obj.message.content === 'string') return obj.message.content;
  return JSON.stringify(obj);
}

const raw = $json;
const rawText = findText(raw);
let parsed = {};
try {
  const match = rawText.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : rawText);
} catch (e) {
  parsed = {};
}

const ctx = $('Build Skill Gap Prompt').item.json;

return { json: {
  chatId: ctx.chatId,
  customerName: ctx.customerName,
  certifications: Array.isArray(parsed.certifications) ? parsed.certifications : [],
  skills: Array.isArray(parsed.skills) ? parsed.skills : [],
  advice: parsed.advice || ''
} };

const j = $json;

let text = '🌟 نصيحة الجمعة لتطوير مسارك المهني

';
text += 'قعدنا نراجع سيرتك الذاتية ووضعك في السوق، وهذي أبرز الأشياء اللي نشوف إنها ترفع فرصك:

';

if (j.certifications && j.certifications.length) {
  text += '🎓 أهم شهادتين نرشحهما لك:

';
  j.certifications.forEach(function(c, i) {
    text += (i + 1) + '. ' + (c.name || '') + '
' + (c.reason ? '💡 ' + c.reason + '
' : '') + '
';
  });
}

if (j.skills && j.skills.length) {
  text += '🛠️ أهم 5 مهارات نرشحها لك تطويرها:

';
  j.skills.forEach(function(s, i) {
    text += (i + 1) + '. ' + (s.name || '') + '
' + (s.reason ? '💡 ' + s.reason + '
' : '') + '
';
  });
}

if (j.advice) {
  text += '📌 نصيحتنا لك:
' + j.advice + '

';
}

text += 'استمر بالتطور، والله يوفقك ويرزقك 🤍';

if (text.length > 4000) {
  text = text.slice(0, 3990) + '…';
}

return { json: { chatId: j.chatId, text: text } };
